import os,sys,tempfile,socket
for key in list(os.environ):
    if any(t in key.upper() for t in ('MYSQL','MONGO','POSTGRES','DATABASE','REDIS','PROXY')): os.environ.pop(key,None)
for key in ('CODE_ASSIST_ENDPOINT','ANTIGRAVITY_API_URL','RESOURCE_MANAGER_API_URL','SERVICE_USAGE_API_URL','GOOGLEAPIS_PROXY_URL','OAUTH_PROXY_URL','KEEPALIVE_URL'): os.environ[key]='http://127.0.0.1:9'
os.environ['PYTHON_DOTENV_DISABLED']='1'
os.environ['GCLI_SERVER_NAME']=''
os.environ['ENABLE_LOG']='0'
os.environ['SMART_429_PROTECTION_ENABLED']='0'
os.environ['PYTHONDONTWRITEBYTECODE']='1'
sys.dont_write_bytecode=True
connect,connect_ex,addr=socket.socket.connect,socket.socket.connect_ex,socket.getaddrinfo
def allowed(address):
    if isinstance(address,tuple) and address[0] not in ('127.0.0.1','::1','localhost'): raise AssertionError('External network forbidden')
def gc(self,address):
    allowed(address)
    return connect(self,address)
def ge(self,address):
    allowed(address)
    return connect_ex(self,address)
def ga(host,*a,**k):
    if host not in ('127.0.0.1','::1','localhost',None): raise AssertionError('External DNS forbidden')
    return addr(host,*a,**k)
socket.socket.connect,socket.socket.connect_ex,socket.getaddrinfo=gc,ge,ga
with tempfile.TemporaryDirectory(prefix='mr-root-core-') as isolated:
    os.environ['CREDENTIALS_DIR']=os.path.join(isolated,'credentials')
    os.makedirs(os.environ['CREDENTIALS_DIR'])
    import asyncio
    from src.storage_adapter import get_storage_adapter
    asyncio.run(get_storage_adapter())
